#include "ksGlobalPairTask.h"
#include <iostream>
#include <stdexcept>
static void check(bool b){if(!b)throw std::runtime_error("Global pair semantic property failed");}
int main(){using T=ks::GlobalPairTask;uint64_t cases=0;auto verify=[&](unsigned selector,uint32_t pair){T t;unsigned reads=0,children=0,guard=0;auto read=[&](bool select)->uint32_t{if(select)return selector;++reads;check(t.index()==uint8_t(selector*4));return pair;};while(t.stage()!=T::Stage::Complete){check(++guard<32);auto child=t.child();if(child!=T::Child::None){if(child==T::Child::First)check(t.first()==uint32_t(uint16_t(pair>>16))<<15);else check(t.second()==uint32_t(uint16_t(pair))<<15);check(t.resumeChild());++children;continue;}auto cost=t.nextClocks(),s=unsigned(t.stage());check(t.advanceBefore(cost-1,read)==0&&unsigned(t.stage())==s);check(t.advanceBefore(cost,read)==cost);}check(reads==1&&children==2);++cases;};for(unsigned selector=0;selector<256;++selector)for(unsigned pattern=0;pattern<256;++pattern)verify(selector,(pattern*0x01010101u)^0xabcdef01);for(unsigned pattern=0;pattern<65536;++pattern)verify(pattern&255,(pattern<<16)|uint16_t(pattern*149));std::cout<<"PASS: "<<cases<<" pure global pair properties; all selectors/byte patterns, full16-bit first/second permutations, wrapped4-byte row index, exact logical halfwords, budget refusal and2child lifetime\n";}
